import os
import sys
import tokenize

root = os.getcwd()
hits = []

for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if d != '.git']
    for name in filenames:
        if not name.endswith('.py'):
            continue
        full = os.path.join(dirpath, name)
        rel = os.path.relpath(full, root).replace(os.sep, '/')
        try:
            with tokenize.open(full) as f:
                for tok in tokenize.generate_tokens(f.readline):
                    if tok.type == tokenize.COMMENT and 'TODO' in tok.string:
                        hits.append((rel, tok.start[0]))
        except (tokenize.TokenError, SyntaxError, UnicodeDecodeError) as e:
            print('skipped %s: %s' % (rel, e), file=sys.stderr)

hits.sort()
with open(os.path.join(root, 'todos.txt'), 'w', encoding='utf-8') as out:
    for rel, line in hits:
        out.write('%s:%d\n' % (rel, line))

print('wrote %d entries' % len(hits))
for rel, line in hits:
    print('%s:%d' % (rel, line))
